84:     recordingsStore: VoiceBroadcastRecordingsStore,
85: ): Promise<boolean> => {
86:     if (client.getSyncState() === SyncState.Error) {
87:         showConnectionErrorDialog();
88:         return false;
89:     }
90: 
91:     if (recordingsStore.getCurrent()) {
92:         showAlreadyRecordingDialog();
93:         return false;
94:     }
95: 
96:     const currentUserId = client.getUserId();
97: 
98:     if (!currentUserId) return false;
99: 
100:     if (!room.currentState.maySendStateEvent(VoiceBroadcastInfoEventType, currentUserId)) {
101:         showInsufficientPermissionsDialog();
102:         return false;
103:     }
104: 
105:     const { hasBroadcast, startedByUser } = await hasRoomLiveVoiceBroadcast(client, room, currentUserId);
