import { getMockClientWithEventEmitter } from "../../test-utils";

describe("pruneClientInformation scratch", () => {
    const deleteAccountData = jest.fn();
    const mockClient = getMockClientWithEventEmitter({
        deleteAccountData,
    });

    beforeEach(() => {
        jest.clearAllMocks();
        (mockClient as any).store = {
            accountData: {
                [getClientInformationEventType("valid-device")]: {},
                [getClientInformationEventType("stale-device")]: {},
                "m.other": {},
            },
        };
    });

    it("does nothing for empty list", () => {
        pruneClientInformation([], mockClient);
        expect(deleteAccountData).not.toHaveBeenCalled();
    });

    it("deletes stale only", () => {
        pruneClientInformation(["valid-device"], mockClient);
        expect(deleteAccountData).toHaveBeenCalledTimes(1);
        expect(deleteAccountData).toHaveBeenCalledWith(getClientInformationEventType("stale-device"));
    });

    it("works with map stores", () => {
        (mockClient as any).store = {
            accountData: new Map([
                [getClientInformationEventType("a"), {}],
                [getClientInformationEventType("b"), {}],
            ]),
        };
        pruneClientInformation(["a"], mockClient);
        expect(deleteAccountData).toHaveBeenCalledWith(getClientInformationEventType("b"));
    });
});
